const rooms = new Map(); // room -> Set<socket>

wss.on("connection", (socket, req) => {
  const user = getUserFromToken(req); // ваша проверка JWT
  let currentRoom = null;

  socket.on("message", (raw) => {
    let data;

    try {
      data = JSON.parse(raw);
    } catch {
      return;
    }

    if (data.type === "join") {
      if (!isValidRoom(data.room)) return;

      if (currentRoom) rooms.get(currentRoom)?.delete(socket);

      currentRoom = data.room;

      if (!rooms.has(currentRoom)) rooms.set(currentRoom, new Set());
      rooms.get(currentRoom).add(socket);

      sendHistory(socket, currentRoom);
    }

    if (data.type === "chat" && currentRoom) {
      const message = {
        type: "chat",
        room: currentRoom,
        username: user.username,
        text: String(data.text).slice(0, 1000)
      };

      insertMessage.run(currentRoom, user.username, message.text);

      for (const client of rooms.get(currentRoom)) {
        if (client.readyState === client.OPEN) {
          client.send(JSON.stringify(message));
        }
      }
    }
  });
});
